// KEUANGAN — Pengeluaran sederhana + kontrol COGS teori vs aktual
// ============================================================
let keuanganPeriod = 'month';

function filterByPeriod(items, getDate, period) {
  const now = new Date();
  return items.filter(item => {
    const d = getDate(item);
    if (period === 'today') return d.toDateString() === now.toDateString();
    if (period === 'week') {
      const weekAgo = new Date(now); weekAgo.setDate(now.getDate() - 6); weekAgo.setHours(0,0,0,0);
      return d >= weekAgo;
    }
    if (period === 'month') return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
    return true; // 'all'
  });
}

function setKeuanganPeriod(period) {
  keuanganPeriod = period;
  ['today','week','month','all'].forEach(p => {
    const el = document.getElementById('kg-' + p);
    if (el) el.classList.toggle('active', p === period);
  });
  const labels = { today: 'Hari ini', week: '7 hari terakhir', month: 'Bulan ini', all: 'Semua periode' };
  document.getElementById('kg-period-label').textContent = labels[period];
  renderKeuangan();
}

function toLocalDateStr(d) {
  const y = d.getFullYear(), m = String(d.getMonth() + 1).padStart(2, '0'), day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function computeIngredientInventoryValue() {
  return state.ingredients.reduce((s, i) => s + (i.stock || 0) * (i.unitCost || 0), 0);
}

function computeProductInventoryValue() {
  return getScopedProducts().reduce((s, p) => s + (p.stock || 0) * (p.cost || 0), 0);
}

// Total gabungan (bahan baku + barang dagang/produk) — dipakai untuk snapshot & kontrol HPP di halaman Keuangan,
// supaya baik F&B (resep) maupun Retail (beli-jual langsung) sama-sama tercakup.
function computeCurrentInventoryValue() {
  return computeIngredientInventoryValue() + computeProductInventoryValue();
}

// Rekam/mutakhirkan nilai persediaan hari ini (dipanggil tiap ada perubahan stok/harga bahan, dan tiap render halaman Keuangan)
// Snapshot ditag businessType supaya kalau device dipakai gantian F&B/Retail, catatan harian tidak saling tiban.
function captureInventorySnapshot() {
  const today = toLocalDateStr(new Date());
  const value = computeCurrentInventoryValue();
  const scoped = filterByBusinessScope(state.inventorySnapshots);
  const existing = scoped.find(s => s.date === today);
  if (existing) existing.value = value;
  else state.inventorySnapshots.push({ date: today, value, businessType: state.businessType || 'all' });
  autoSave();
}

// Cari snapshot nilai persediaan pada atau sebelum tanggal tertentu (untuk "persediaan awal"), khusus tipe bisnis aktif
function getInventoryValueOnOrBefore(targetDateStr) {
  if (!targetDateStr) return null;
  const candidates = filterByBusinessScope(state.inventorySnapshots)
    .filter(s => s.date <= targetDateStr).sort((a, b) => (a.date < b.date ? 1 : -1));
  return candidates.length ? candidates[0].value : null;
}

function getPeriodStartDateStr(period) {
  const now = new Date();
  if (period === 'today') return toLocalDateStr(now);
  if (period === 'week') { const d = new Date(now); d.setDate(now.getDate() - 6); return toLocalDateStr(d); }
  if (period === 'month') return toLocalDateStr(new Date(now.getFullYear(), now.getMonth(), 1));
  return null; // 'all' — tidak ada batas bawah, pakai snapshot paling awal yang tersedia
}

function populateExpenseIngredientSelect() {
  const sel = document.getElementById('exp-ingredient');
  if (!sel) return;
  sel.innerHTML = state.ingredients.map(i => `<option value="${i.id}">${i.name} (stok: ${i.stock || 0} ${i.unit})</option>`).join('');
  onExpenseIngredientChange();
}

function onExpenseIngredientChange() {
  const sel = document.getElementById('exp-ingredient');
  const ing = state.ingredients.find(i => String(i.id) === String(sel.value));
  document.getElementById('exp-qty-unit').value = ing ? ing.unit : '';
}

function populateExpenseProductSelect() {
  const sel = document.getElementById('exp-product');
  if (!sel) return;
  sel.innerHTML = getScopedProducts().map(p => `<option value="${p.id}">${p.name} (stok: ${p.stock || 0})</option>`).join('');
}

function toggleExpenseCategoryCustom() {
  const sel = document.getElementById('exp-category');
  document.getElementById('exp-category-custom').classList.toggle('hidden', sel.value !== '__custom__');
  const isIngredientPurchase = sel.value === 'Pembelian Bahan Baku';
  const isProductPurchase = sel.value === 'Pembelian Barang Dagang';
  document.getElementById('exp-ingredient-fields').classList.toggle('hidden', !isIngredientPurchase);
  document.getElementById('exp-product-fields').classList.toggle('hidden', !isProductPurchase);
  document.getElementById('exp-amount-label').textContent = (isIngredientPurchase || isProductPurchase) ? 'Total Harga Pembelian (Rp)' : 'Jumlah (Rp)';
  if (isIngredientPurchase) populateExpenseIngredientSelect();
  if (isProductPurchase) populateExpenseProductSelect();
}

function addExpense() {
  const dateVal = document.getElementById('exp-date').value;
  const catSel  = document.getElementById('exp-category').value;
  const category = catSel === '__custom__' ? document.getElementById('exp-category-custom').value.trim() : catSel;
  const amount  = parseInt(document.getElementById('exp-amount').value) || 0;
  const note    = document.getElementById('exp-note').value.trim();
  const isIngredientPurchase = category === 'Pembelian Bahan Baku';
  const isProductPurchase = category === 'Pembelian Barang Dagang';

  if (!dateVal) { showToast('Tanggal wajib diisi!'); return; }
  if (!category) { showToast('Kategori wajib diisi!'); return; }
  if (amount <= 0) { showToast('Jumlah harus lebih dari 0!'); return; }

  let ingredientId = null, qty = null, productId = null;

  if (isIngredientPurchase) {
    const ingSel = document.getElementById('exp-ingredient').value;
    qty = parseFloat(document.getElementById('exp-qty').value) || 0;
    if (!ingSel) { showToast('Pilih bahan yang dibeli!'); return; }
    if (qty <= 0) { showToast('Qty dibeli harus lebih dari 0!'); return; }
    const ing = state.ingredients.find(i => String(i.id) === String(ingSel));
    if (!ing) { showToast('Bahan tidak ditemukan!'); return; }
    ingredientId = ing.id;
    // Update stok + harga rata-rata tertimbang berdasarkan pembelian baru
    const oldValue = (ing.stock || 0) * (ing.unitCost || 0);
    const newStock = (ing.stock || 0) + qty;
    ing.stock = newStock;
    ing.unitCost = newStock > 0 ? Math.round((oldValue + amount) / newStock) : ing.unitCost;
  }

  if (isProductPurchase) {
    const prodSel = document.getElementById('exp-product').value;
    qty = parseFloat(document.getElementById('exp-product-qty').value) || 0;
    if (!prodSel) { showToast('Pilih produk yang dibeli!'); return; }
    if (qty <= 0) { showToast('Qty dibeli harus lebih dari 0!'); return; }
    const prod = state.products.find(p => String(p.id) === String(prodSel));
    if (!prod) { showToast('Produk tidak ditemukan!'); return; }
    productId = prod.id;
    // Update stok + harga modal rata-rata tertimbang berdasarkan pembelian baru
    const oldValue = (prod.stock || 0) * (prod.cost || 0);
    const newStock = (prod.stock || 0) + qty;
    prod.stock = newStock;
    prod.cost = newStock > 0 ? Math.round((oldValue + amount) / newStock) : prod.cost;
  }

  state.expenses.unshift({ id: state.nextExpenseId++, date: new Date(dateVal), category, amount, note, ingredientId, qty, productId, businessType: state.businessType || 'all' });
  if (isIngredientPurchase || isProductPurchase) captureInventorySnapshot(); else autoSave();
  addLog('sistem', 'sukses', 'Pengeluaran dicatat', `${category} · ${fmt(amount)}${note ? ' · ' + note : ''}`);
  showToast('✓ Pengeluaran dicatat');

  document.getElementById('exp-amount').value = '';
  document.getElementById('exp-note').value = '';
  document.getElementById('exp-qty').value = '';
  document.getElementById('exp-product-qty').value = '';
  document.getElementById('exp-category').value = 'Pembelian Bahan Baku';
  document.getElementById('exp-category-custom').classList.add('hidden');
  document.getElementById('exp-category-custom').value = '';
  toggleExpenseCategoryCustom();

  renderExpenseList();
  renderKeuangan();
  if (isProductPurchase && document.getElementById('page-inventory').classList.contains('active')) renderInventory();
}

function deleteExpense(id) {
  const exp = state.expenses.find(e => e.id === id);
  state.expenses = state.expenses.filter(e => e.id !== id);
  // Catatan: hapus pengeluaran "Pembelian Bahan Baku" TIDAK membalik stok/harga bahan secara otomatis,
  // karena harga rata-rata tertimbang sudah tercampur dengan pembelian lain. Kalau salah input, sesuaikan stok manual di Kelola Bahan Baku.
  autoSave();
  if (exp) addLog('sistem', 'warning', 'Pengeluaran dihapus', `${exp.category} · ${fmt(exp.amount)}`);
  renderExpenseList();
  renderKeuangan();
}

function renderExpenseList() {
  const filtered = filterByPeriod(filterByBusinessScope(state.expenses), e => e.date, keuanganPeriod)
    .sort((a, b) => b.date - a.date);
  const el = document.getElementById('kg-expense-list');
  const empty = document.getElementById('kg-expense-empty');
  const countLabel = document.getElementById('kg-expense-count-label');
  countLabel.textContent = `${filtered.length} tercatat`;

  if (filtered.length === 0) {
    el.innerHTML = '';
    empty.style.display = '';
    return;
  }
  empty.style.display = 'none';
  el.innerHTML = filtered.map(e => `
    <div class="flex items-center gap-3 px-4 py-3 hover:bg-surface-muted transition-colors">
      <div class="w-9 h-9 rounded-xl flex items-center justify-center shrink-0 ${e.category === 'Pembelian Bahan Baku' ? 'bg-amber-50' : e.category === 'Pembelian Barang Dagang' ? 'bg-blue-50' : 'bg-ink-50'}">
        <span class="text-base">${e.category === 'Pembelian Bahan Baku' ? '🧂' : e.category === 'Pembelian Barang Dagang' ? '📦' : '💸'}</span>
      </div>
      <div class="flex-1 min-w-0">
        <p class="text-[13px] font-semibold text-ink-800">${e.category}${e.qty ? ` · ${e.qty}` : ''}</p>
        <p class="text-[11px] text-ink-400">${fmtDate(e.date)}${e.note ? ' · ' + e.note : ''}</p>
      </div>
      <span class="font-bold text-sm tnum shrink-0 text-ink-800">${fmt(e.amount)}</span>
      <button onclick="deleteExpense(${e.id})" class="shrink-0 w-7 h-7 rounded-lg text-ink-300 hover:bg-red-50 hover:text-red-500 flex items-center justify-center transition-colors" title="Hapus">
        <svg class="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M6 18L18 6M6 6l12 12"/></svg>
      </button>
    </div>`).join('');
}

