function addReconciliationEntry() {
  if (state.currentShift) { showToast('⚠️ Tutup shift dulu sebelum mencatat rekonsiliasi.'); return; }
  const dateVal = document.getElementById('recon-date').value;
  const method  = document.getElementById('recon-method').value;
  const amount  = parseInt(document.getElementById('recon-amount').value) || 0;
  const note    = document.getElementById('recon-note').value.trim();

  if (!dateVal) { showToast('Tanggal wajib diisi!'); return; }
  if (!method) { showToast('Pilih metode pembayaran!'); return; }
  if (amount <= 0) { showToast('Jumlah harus lebih dari 0!'); return; }

  state.reconciliations.push({ id: state.nextReconciliationId++, date: new Date(dateVal), method, actualAmount: amount, note, businessType: state.businessType || 'all' });
  autoSave();
  addLog('sistem', 'sukses', 'Saldo diterima aktual dicatat', `${method} · ${fmt(amount)}${note ? ' · ' + note : ''}`);
  showToast('✓ Saldo diterima dicatat');

  document.getElementById('recon-amount').value = '';
  document.getElementById('recon-note').value = '';
  renderKeuangan();
}

function computeReconciliationData(period) {
  const txs = filterByPeriod(filterByBusinessScope(state.transactions).filter(t => !t.voided), tx => tx.date, period);
  const recons = filterByPeriod(filterByBusinessScope(state.reconciliations), r => r.date, period);

  const byMethod = {}; // method -> {count, totalPOS}
  txs.forEach(tx => {
    (tx.payments || []).forEach(p => {
      if (!byMethod[p.method]) byMethod[p.method] = { count: 0, totalPOS: 0 };
      byMethod[p.method].count += 1;
      byMethod[p.method].totalPOS += p.amount;
    });
  });

  return Object.keys(byMethod).map(method => {
    const { count, totalPOS } = byMethod[method];
    const feePct = getMerchantFeePercent(method);
    const merchantFee = Math.round(totalPOS * feePct / 100);
    const estimasiNet = totalPOS - merchantFee;
    const actualReceived = recons.filter(r => r.method === method).reduce((s, r) => s + r.actualAmount, 0);
    const hasActual = recons.some(r => r.method === method);
    const selisih = hasActual ? actualReceived - estimasiNet : null;
    return { method, count, totalPOS, feePct, merchantFee, estimasiNet, actualReceived, hasActual, selisih };
  }).sort((a, b) => b.totalPOS - a.totalPOS);
}

function renderReconciliationTable() {
  const data = computeReconciliationData(keuanganPeriod);
  const tbody = document.getElementById('kg-recon-table');
  const tfoot = document.getElementById('kg-recon-footer');
  const empty = document.getElementById('kg-recon-empty');

  if (data.length === 0) {
    tbody.innerHTML = '';
    tfoot.innerHTML = '';
    empty.classList.remove('hidden');
    return;
  }
  empty.classList.add('hidden');

  tbody.innerHTML = data.map(d => {
    const selisihHTML = d.hasActual
      ? `<span class="font-semibold ${Math.abs(d.selisih) < 100 ? 'text-brand-600' : (d.selisih < 0 ? 'text-red-500' : 'text-amber-600')}">${d.selisih > 0 ? '+' : ''}${fmt(d.selisih)}</span>`
      : `<span class="text-ink-300">belum dicatat</span>`;
    return `<tr class="border-t border-surface-border">
      <td class="px-3 py-2.5 text-sm font-medium text-ink-800">${d.method}<span class="block text-[10px] text-ink-400 font-normal">${d.count} transaksi</span></td>
      <td class="px-3 py-2.5 text-right text-sm tnum text-ink-700">${fmt(d.totalPOS)}</td>
      <td class="px-3 py-2.5 text-center">
        <input type="number" step="0.1" value="${d.feePct}" onchange="setMerchantFeePercent('${d.method.replace(/'/g,"\\'")}', this.value)" class="w-14 text-center text-xs border border-surface-border rounded-md py-1 px-1" />%
      </td>
      <td class="px-3 py-2.5 text-right text-sm tnum text-red-500">${d.merchantFee > 0 ? '−' + fmt(d.merchantFee) : fmt(0)}</td>
      <td class="px-3 py-2.5 text-right text-sm font-semibold tnum text-ink-800">${fmt(d.estimasiNet)}</td>
      <td class="px-3 py-2.5 text-right text-sm tnum text-ink-700">${d.hasActual ? fmt(d.actualReceived) : '—'}</td>
      <td class="px-3 py-2.5 text-right text-sm tnum">${selisihHTML}</td>
    </tr>`;
  }).join('');

  const totalPOS = data.reduce((s, d) => s + d.totalPOS, 0);
  const totalFee = data.reduce((s, d) => s + d.merchantFee, 0);
  const totalNet = data.reduce((s, d) => s + d.estimasiNet, 0);
  const totalActual = data.reduce((s, d) => s + (d.hasActual ? d.actualReceived : 0), 0);
  tfoot.innerHTML = `<tr class="border-t-2 border-surface-border bg-surface-muted font-bold">
    <td class="px-3 py-2.5 text-sm text-ink-800">Total</td>
    <td class="px-3 py-2.5 text-right text-sm tnum text-ink-800">${fmt(totalPOS)}</td>
    <td class="px-3 py-2.5"></td>
    <td class="px-3 py-2.5 text-right text-sm tnum text-red-500">−${fmt(totalFee)}</td>
    <td class="px-3 py-2.5 text-right text-sm tnum text-ink-800">${fmt(totalNet)}</td>
    <td class="px-3 py-2.5 text-right text-sm tnum text-ink-800">${fmt(totalActual)}</td>
    <td class="px-3 py-2.5"></td>
  </tr>`;
}

function renderKeuangan() {
  // Default tanggal input ke hari ini kalau masih kosong
  const dateInput = document.getElementById('exp-date');
  if (dateInput && !dateInput.value) dateInput.value = toLocalDateStr(new Date());
  const reconDateInput = document.getElementById('recon-date');
  if (reconDateInput && !reconDateInput.value) reconDateInput.value = toLocalDateStr(new Date());
  populateReconMethodSelect();
  updateReconciliationLockState();
  toggleExpenseCategoryCustom();

  captureInventorySnapshot(); // pastikan snapshot hari ini terbaru sebelum dihitung
  renderOpeningInventoryInfo();

  const txs = filterByPeriod(filterByBusinessScope(state.transactions).filter(t => !t.voided), tx => tx.date, keuanganPeriod);
  const revenue    = txs.reduce((s, tx) => s + tx.total, 0);
  const cogsTeori  = txs.reduce((s, tx) => s + (tx.totalCost || 0), 0);

  const exps = filterByPeriod(filterByBusinessScope(state.expenses), e => e.date, keuanganPeriod);
  const purchaseExp    = exps.filter(e => e.category === 'Pembelian Bahan Baku' || e.category === 'Pembelian Barang Dagang');
  const totalPembelian = purchaseExp.reduce((s, e) => s + e.amount, 0);
  const otherExpenses  = exps.filter(e => e.category !== 'Pembelian Bahan Baku' && e.category !== 'Pembelian Barang Dagang');
  const totalOtherExp  = otherExpenses.reduce((s, e) => s + e.amount, 0);

  // ── Persediaan Awal & Akhir (metode persediaan periodik) ──
  const closingValue = computeCurrentInventoryValue();
  const periodStartStr = getPeriodStartDateStr(keuanganPeriod);
  let openingValue;
  let usedFallback = false;
  if (periodStartStr) {
    const dayBefore = new Date(periodStartStr + 'T00:00:00'); dayBefore.setDate(dayBefore.getDate() - 1);
    openingValue = getInventoryValueOnOrBefore(toLocalDateStr(dayBefore));
  } else {
    const sorted = [...state.inventorySnapshots].sort((a, b) => (a.date < b.date ? -1 : 1));
    openingValue = sorted.length ? sorted[0].value : null;
  }
  if (openingValue === null) { openingValue = closingValue; usedFallback = true; }

  const cogsAktual = openingValue + totalPembelian - closingValue;
  const netProfit  = revenue - cogsAktual - totalOtherExp;

  document.getElementById('kg-revenue').textContent    = fmt(revenue);
  document.getElementById('kg-expenses').textContent   = fmt(totalOtherExp);
  document.getElementById('kg-net-profit').textContent = fmt(netProfit);

  // Kontrol COGS teori vs aktual
  document.getElementById('kg-cogs-teori').textContent  = fmt(cogsTeori);
  document.getElementById('kg-cogs-aktual').textContent = fmt(cogsAktual);
  document.getElementById('kg-inv-awal').textContent    = fmt(openingValue);
  document.getElementById('kg-inv-beli').textContent    = fmt(totalPembelian);
  document.getElementById('kg-inv-akhir').textContent   = fmt(closingValue);

  const selisih = cogsAktual - cogsTeori;
  const selisihPct = cogsTeori > 0 ? Math.round((selisih / cogsTeori) * 100) : 0;
  const selisihBox = document.getElementById('kg-cogs-selisih-box');
  const selisihEl  = document.getElementById('kg-cogs-selisih');
  const noteEl     = document.getElementById('kg-cogs-note');
  const sign = selisih > 0 ? '+' : '';
  selisihEl.textContent = `${sign}${fmt(selisih)} (${sign}${selisihPct}%)`;

  if (usedFallback) {
    selisihBox.className = 'rounded-xl p-3 flex items-center justify-between bg-ink-50 text-ink-500';
    noteEl.textContent = 'Belum ada histori persediaan sebelum periode ini, jadi Persediaan Awal disamakan dengan Persediaan Akhir (COGS Aktual = Total Pembelian saja untuk sementara). Akurasi akan membaik setelah beberapa hari histori snapshot terkumpul.';
  } else if (cogsTeori === 0) {
    selisihBox.className = 'rounded-xl p-3 flex items-center justify-between bg-ink-50 text-ink-500';
    noteEl.textContent = 'Belum ada penjualan dengan resep HPP di periode ini — COGS Teori belum bisa dibandingkan.';
  } else if (Math.abs(selisihPct) <= 10) {
    selisihBox.className = 'rounded-xl p-3 flex items-center justify-between bg-brand-50 text-brand-700';
    noteEl.textContent = 'Selisih wajar (≤10%) — pemakaian bahan baku aktual cukup sejalan dengan teori resep.';
  } else if (selisih > 0) {
    selisihBox.className = 'rounded-xl p-3 flex items-center justify-between bg-red-50 text-red-600';
    noteEl.textContent = 'Konsumsi bahan baku aktual lebih besar dari teori resep — indikasi waste, porsi kelebihan takaran, atau bahan terpakai di luar resep tercatat.';
  } else {
    selisihBox.className = 'rounded-xl p-3 flex items-center justify-between bg-amber-50 text-amber-700';
    noteEl.textContent = 'Konsumsi bahan baku aktual lebih kecil dari teori resep — kemungkinan ada efisiensi, atau resep belum mencerminkan pemakaian bahan yang sesungguhnya.';
  }

  renderExpenseList();
