(function(){
  const selects = Array.from(document.querySelectorAll('select'));
  const catSelect = selects.find(s => s.value === 'Pembelian Bahan Baku');
  if (!catSelect) return 'not found';
  const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLSelectElement.prototype, 'value').set;
  nativeSetter.call(catSelect, 'Lain-lain');
  catSelect.dispatchEvent(new Event('change', { bubbles: true }));
  return 'set to ' + catSelect.value;
})()

(function(){
  const btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('Tambah Pengeluaran'));
  if (!btn) return 'not found';
  btn.click();
  return 'clicked';
})()

